      "nameEn": "Fellowship with Men (Tong Ren)",
      "nameZh": "天火同人",
      "pinyin": "Tiān huǒ tóng rén",
      "guaCiZh": "同人于野，亨。利涉大川，利君子贞。",
      "guaCiHanViet": "Đồng nhân vu dã, hanh. Lợi thiệp đại xuyên, lợi quân tử trinh.",
      "daXiangZh": "天与火，同人。君子以类族辨物。",
      "daXiangVi": "Trời cao và lửa sáng cùng hướng lên tạo tượng đồng tâm; người quân tử noi theo đó mà phân loại rõ ràng các nhóm và sự vật để hợp tác hài hòa.",
      "daXiangEn": "Heaven and fire rise together in fellowship; thus the noble person classifies groups and distinguishes matters clearly.",
      "lineMeanings6": [
        "Hào Sơ: 同人于门，无咎 (Đồng nhân vu môn, vô cữu) — Mở rộng hợp tác ra ngoài phạm vi khép kín bằng thái độ công khai, không thiên vị sẽ tránh được sai sót.",
        "Hào Nhị: 同人于宗，吝 (Đồng nhân vu tông, lận) — Chỉ hợp tác trong nhóm lợi ích hẹp hay phe cánh thân quen sẽ làm thu hẹp tầm nhìn và gây trì trệ.",
        "Hào Tam: 伏戎于莽，升其高陵，三岁不兴 (Phục nhung vu mãng, thăng kỳ cao lăng, tam tuế bất hưng) — Nghi kỵ và tính toán đối phó ngầm khiến tổ chức tiêu hao năng lượng mà không đạt được tiến bộ.",
        "Hào Tứ: 乘其墉，弗克攻，吉 (Thừa kỳ dung, phất khắc công, cát) — Nhận ra giới hạn của đối đầu và chủ động quay về đối thoại xây dựng là quyết định sáng suốt.",
        "Hào Ngũ: 同人，先号咷而后笑 (Đồng nhân, tiên hiệu đào nhi hậu tiếu) — Sự đồng thuận đích thực đôi khi phải trải qua tranh luận gay gắt và tháo gỡ rào cản trước khi đạt được thấu hiểu.",
        "Hào Thượng: 同人于郊，无悔 (Đồng nhân vu giao, vô hối) — Giữ quan hệ cộng tác chừng mực, ôn hòa và tôn trọng ranh giới dù chưa đạt đồng thuận tuyệt đối vẫn giúp tránh hối tiếc."
      ],
      "leadershipAndEthicsVi": "Quẻ Đồng Nhân đặt nền tảng cho tinh thần hợp tác rộng mở vượt lên trên lợi ích nhóm hay định kiến cục bộ. Trong xây dựng đội ngũ và cộng đồng, sự đoàn kết thực chất đòi hỏi minh bạch mục tiêu chung, tôn trọng sự khác biệt qua phân vai rành mạch, loại bỏ tâm lý nghi kỵ và sẵn sàng đối thoại thẳng thắn để đi đến đồng thuận bền vững.",
      "leadershipAndEthicsEn": "Tong Ren sets forth a philosophy of broad, principled cooperation that transcends narrow cliques. True organizational unity requires transparent shared goals, clear differentiation of roles and perspectives, rejection of covert suspicion, and willingness to work through difficult disagreements toward genuine alignment."
