      "nameVi": "Lôi Địa Dự",
      "nameEn": "Enthusiasm (Yu)",
      "nameZh": "雷地豫",
      "pinyin": "Léi dì yù",
      "guaCiZh": "豫，利建侯行师。",
      "guaCiHanViet": "Dự, lợi kiến hầu hành sư.",
      "daXiangZh": "雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。",
      "daXiangVi": "Sấm vang dậy từ lòng đất làm vạn vật phấn chấn, đó là tượng quẻ Dự; bậc tiên vương noi theo đó mà dùng âm nhạc tôn vinh đạo đức và gắn kết tinh thần cộng đồng.",
      "daXiangEn": "Thunder bursts forth from the earth with energizing momentum; thus the ancient kings created music to honor virtue and elevate collective spirit.",
      "lineMeanings6": [
        "Hào Sơ: 鸣豫，凶 (Minh dự, hung) — Vừa có chút thuận lợi đã vội phô trương tự đắc sẽ nhanh chóng đánh mất sự tỉnh táo và chuốc lấy thất bại.",
        "Hào Nhị: 介于石，不终日，贞吉 (Giới vu thạch, bất chung nhật, trinh cát) — Giữ lập trường vững chắc như đá và nhận diện kịp thời điểm chuyển biến của sự việc giúp tránh sa đà vào hưởng lạc.",
        "Hào Tam: 盱豫，悔，迟有悔 (Hu dự, hối, trì hữu hối) — Dựa dẫm vào quyền lực người khác để cầu an và chần chừ tự sửa đổi sẽ dẫn đến hối tiếc.",
        "Hào Tứ: 由豫，大有得，勿疑，朋盍簪 (Do dự, đại hữu đắc, vật nghi, bằng hạp trâm) — Người tạo dựng được động lực chung bằng sự chân thành và tin tưởng sẽ quy tụ được đông đảo cộng sự đồng lòng.",
        "Hào Ngũ: 贞疾，恒不死 (Trinh tật, hằng bất tử) — Khi chịu áp lực dài hạn hoặc bị lấn át, ý thức cảnh giác thường trực lại chính là yếu tố giúp hệ thống duy trì sức sống.",
        "Hào Thượng: 冥豫，成有渝，无咎 (Minh dự, thành hữu du, vô cữu) — Say sưa trong thành công đến mức mất phương hướng rất nguy hiểm, nhưng nếu kịp thời tỉnh ngộ và cải tổ thì vẫn khắc phục được."
      ],
      "leadershipAndEthicsVi": "Quẻ Dự thể hiện đồng thời hai tầng nghĩa là sự phấn chấn lan tỏa và tinh thần dự phòng chuẩn bị trước. Trong quản trị, tạo cảm hứng và sự đồng thuận văn hóa giúp huy động sức mạnh tập thể hiệu quả, song nhà lãnh đạo phải giữ đầu óc tỉnh táo như đá tảng, đọc sớm dấu hiệu tự mãn và kịp thời điều chỉnh khi nhiệt huyết chuyển thành chủ quan.",
      "leadershipAndEthicsEn": "Yu integrates two complementary dimensions: inspiring collective enthusiasm and exercising foresight. In leadership, cultivating shared cultural energy mobilizes people effectively, yet leaders must remain grounded, detect early signs of complacency or dependence, and course-correct promptly whenever excitement threatens sound judgment."
