        "classicalNoteEn": "The heart of the Azure Dragon, centered on the bright red supergiant Antares (Great Fire, Xin Xiu Er). The Classic of Poetry cites the westward drift of Great Fire in the seventh lunar month as a seasonal marker of approaching autumn."
