    "cscGuidePillars": [
      {
        "stepNum": 1,
        "titleVi": "Phân loại kênh nộp CSC Type A (Song phương) và Type B (Trường tự chủ)",
        "titleEn": "Distinguishing CSC Type A (Bilateral) and Type B (University Track)",
        "detailVi": "CSC Type A nộp qua cơ quan cử tuyển quốc gia (tại Việt Nam là Cục Hợp tác Quốc tế – Bộ Giáo dục và Đào tạo hoặc Đại sứ quán Trung Quốc), cho phép chọn tối đa 3 nguyện vọng trường và ưu tiên hồ sơ có Thư dự tuyển (Pre-admission Letter). CSC Type B nộp trực tiếp vào một trường đại học được ủy quyền (nhập đúng mã 5 chữ số cscCode trên cổng campuschina.org), hiện quy định mỗi thí sinh chỉ duy trì 1 hồ sơ Type B hiệu lực tại một thời điểm để tránh trùng lặp xét duyệt.",
        "detailEn": "CSC Type A routes through national dispatching authorities (such as Vietnam's MOET International Cooperation Department or the Chinese Embassy), allowing up to three university preferences and rewarding Pre-admission Letters. CSC Type B submits directly to an authorized university using its exact 5-digit cscCode on campuschina.org; current rules allow one active Type B application at a time."
      },
      {
        "stepNum": 2,
        "titleVi": "Chọn trường, đối chiếu mã cscCode và liên hệ giáo sư hướng dẫn (Sáo từ / 套磁)",
        "titleEn": "Selecting Universities, Verifying cscCode, and Faculty Outreach (Taoci)",
        "detailVi": "Từ tháng 09 đến tháng 11 hằng năm, rà soát danh mục ngành mở tuyển quốc tế của 24 trường 985, xác nhận ngôn ngữ giảng dạy (tiếng Trung yêu cầu HSK 5–6; tiếng Anh yêu cầu IELTS 6.0–7.0 hoặc TOEFL 80–100). Gửi email học thuật ngắn gọn cho giáo sư có cùng hướng nghiên cứu kèm CV học thuật, bảng điểm và tóm tắt ý tưởng 1 trang để xin thư chấp nhận sơ bộ (Acceptance Letter) trước khi cổng nộp mở.",
        "detailEn": "Between September and November each year, verify open international degree catalogs across Project 985 universities and confirm language thresholds (HSK 5–6 for Chinese tracks; IELTS 6.0–7.0 or TOEFL 80–100 for English tracks). Send concise outreach emails to aligned supervisors attaching an academic CV, transcript, and one-page research abstract to request a supervisor acceptance letter before portals open."
      },
      {
        "stepNum": 3,
        "titleVi": "Chuẩn hóa bộ hồ sơ pháp lý và học thuật (Tháng 11 – Tháng 01)",
        "titleEn": "Preparing Legalized and Academic Documentation (Nov–Jan)",
        "detailVi": "Hoàn thiện đầy đủ các giấy tờ bắt buộc: hộ chiếu còn hạn tối thiểu 12 tháng, bằng tốt nghiệp và bảng điểm dịch công chứng Anh/Trung (sinh viên năm cuối nộp Giấy xác nhận dự kiến tốt nghiệp), 2 Thư giới thiệu từ Phó Giáo sư hoặc Giáo sư ký tay trên giấy tiêu đề trường, Giấy khám sức khỏe người nước ngoài (Foreigner Physical Examination Form có giá trị 6 tháng), Phiếu lý lịch tư pháp (Không tiền án tiền sự còn hạn 6 tháng) và chứng chỉ ngoại ngữ.",
        "detailEn": "Compile mandatory dossiers: passport valid for at least 12 months, notarized English/Chinese diplomas and transcripts (or expected-graduation certificate for final-year students), two recommendation letters signed by Associate or Full Professors on institutional letterhead, the Foreigner Physical Examination Form (valid 6 months), a Non-Criminal Record Certificate (valid 6 months), and valid language certificates."
      },
      {
        "stepNum": 4,
        "titleVi": "Khung dàn ý Study Plan / Research Proposal 1.500 chữ song ngữ (Phần 1: Vấn đề & Tổng quan)",
        "titleEn": "1,500-Word Bilingual Study Plan / Research Proposal Blueprint (Part 1: Problem & Literature)",
        "detailVi": "Mục 1 – Tựa đề & Tóm tắt học thuật (150 chữ): nêu rõ đối tượng, phạm vi địa lý – thời gian và đóng góp cốt lõi. Mục 2 – Đặt vấn đề & Khoảng trống nghiên cứu (350 chữ): chỉ rõ mâu thuẫn lý thuyết hoặc thực tiễn chưa được giải quyết trong 3–5 nghiên cứu gần nhất (trích dẫn chuẩn APA/GB/T 7714). Mục 3 – Mục tiêu & Câu hỏi nghiên cứu (200 chữ): thiết kế 2–3 câu hỏi nghiên cứu đo lường được và giả thuyết kiểm định rõ ràng.",
        "detailEn": "Section 1 – Title & Abstract (150 words): state the object, spatial-temporal scope, and core contribution. Section 2 – Research Problem & Literature Gap (350 words): identify unresolved theoretical or empirical gaps across 3–5 recent peer-reviewed works (formatted in APA or GB/T 7714). Section 3 – Objectives & Research Questions (200 words): formulate 2–3 measurable research questions and testable hypotheses."
      },
      {
        "stepNum": 5,
        "titleVi": "Khung dàn ý Study Plan / Research Proposal 1.500 chữ song ngữ (Phần 2: Phương pháp & Lộ trình)",
        "titleEn": "1,500-Word Bilingual Study Plan / Research Proposal Blueprint (Part 2: Methodology & Timeline)",
        "detailVi": "Mục 4 – Phương pháp luận & Dữ liệu (400 chữ): mô tả mô hình định lượng (kinh tế lượng, SEM, học máy) hoặc định tính (khảo chứng văn hiến, điền dã so sánh), nguồn dữ liệu và công cụ xử lý. Mục 5 – Lộ trình thực hiện theo học kỳ & Sự phù hợp với trường (250 chữ): chia mốc theo từng năm học, gắn trực tiếp với phòng thí nghiệm hoặc hướng nghiên cứu của giáo sư. Mục 6 – Tài liệu tham khảo chọn lọc (150 chữ): 8–12 nguồn học thuật uy tín (SSCI/SCI/CSSCI).",
        "detailEn": "Section 4 – Methodology & Data Sources (400 words): specify quantitative models (econometrics, SEM, machine learning) or qualitative methods (textual philology, comparative fieldwork), datasets, and analytical tools. Section 5 – Semester Timeline & Institutional Fit (250 words): map milestones by academic year, linking directly to the target lab or supervisor. Section 6 – Key References (150 words): cite 8–12 authoritative works (SSCI/SCI/CSSCI)."
      },
      {
        "stepNum": 6,
        "titleVi": "Nộp đơn song song, phỏng vấn học thuật và hoàn tất thủ tục thị thực X1 (Tháng 02 – Tháng 08)",
        "titleEn": "Dual Portal Submission, Academic Interview, and X1 Visa Procedures (Feb–Aug)",
        "detailVi": "Nộp đồng thời trên hệ thống campuschina.org (chọn đúng Type A/B và cscCode) và cổng tuyển sinh riêng của trường trước hạn (đa số trường 985 đóng từ cuối tháng 02 đến cuối tháng 03). Chuẩn bị bài thuyết trình 5 phút về Proposal cho vòng phỏng vấn trực tuyến (tháng 04–05). Sau khi nhận kết quả chính thức và mẫu JW201 cùng Giấy báo trúng tuyển (tháng 06–07), tiến hành xin thị thực X1 nhập học tháng 09.",
        "detailEn": "Submit concurrently on campuschina.org (verifying Type A/B and cscCode) and the university's internal portal before deadlines (most Project 985 schools close between late February and late March). Prepare a five-minute proposal pitch for online interviews (April–May). Upon receiving the official Admission Notice and JW201 form (June–July), apply for the X1 student visa ahead of September matriculation."
      }
    ],
